c = Hash.new(0)
%w[a b a].each { |w| c[w] += 1 }
puts c.inspect # {"a"=>2, "b"=>1}

def apply_to_all(arr)
  result = []
  arr.each { |x| result << yield(x) }
  result
end
p apply_to_all([1, 2, 3]) { |n| n * 3 } # [3, 6, 9]
